      {},
      user,
    ),
  onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  onError: (_e, id) =>
    setRefused({ id, message: 'Only a steward can waive the late charge of an OPEN or PENDING claim, once.' }),
});

